#include <cmath>
#include <algorithm>
extern "C" void render_c(double* pts,int N,int res,double angle,float* out){
 double px=227.18450651397864/res,rx=pts[0],ry=pts[1],w=0,d=0,th=angle;
 for(int j=0;j<N;j++){
 double x=pts[3*j],y=pts[3*j+1],z=std::clamp(pts[3*j+2],0.,15.);
 double W=z>0?std::max(0.,1.187*z-.3):0.,D=z>0?1.38+1.075*z:0.,O=z>0?std::max(0.,11.15-.0967*pow(z-10.91,2)):0.;
 w=.02*w+.98*W;d=.02*d+.98*D;
 double vx=x-rx,vy=y-ry,L=hypot(vx,vy),o=std::min(O,L);
 if(L>(z>0?1.:.1)) th=atan2(vy,vx);
 if(L>0){rx=x-vx*o/L;ry=y-vy*o/L;}
 if(w<.001)continue;
 double ex=cos(th),ey=sin(th),nx=-ey,ny=ex,hw=w/2;
 double xs[]={rx+hw*nx,rx-hw*nx,rx-d*ex+hw*nx,rx-d*ex-hw*nx},ys[]={ry+hw*ny,ry-hw*ny,ry-d*ey+hw*ny,ry-d*ey-hw*ny};
 int u0=std::max(0,int(floor(*std::min_element(xs,xs+4)/px))-2),u1=std::min(res,int(ceil(*std::max_element(xs,xs+4)/px))+2);
 int v0=std::max(0,int(floor(*std::min_element(ys,ys+4)/px))-2),v1=std::min(res,int(ceil(*std::max_element(ys,ys+4)/px))+2);
 for(int v=v0;v<v1;v++)for(int u=u0;u<u1;u++){
 double qx=(u+.5)*px-rx,qy=(v+.5)*px-ry,s=-(qx*ex+qy*ey),t=qx*nx+qy*ny;
 double f=d*(1-4*t*t/(w*w))-s,g=sqrt(1+pow(8*d*t/(w*w),2));
 float a=std::clamp(std::min(s,f/g)/px+.5,0.,1.);
 out[v*res+u]=std::max(out[v*res+u],a);
 }
 }
}
